---@class CommonGoodsListLight
---@field GoodNode                      	UnityEngine.RectTransform
local CommonGoodsListLight = Class("CommonGoodsListLight")
function CommonGoodsListLight:__init()
    self.data = {}
    self.goodNodeList = {}

end

function CommonGoodsListLight:__delete()
    self.controller = nil
    self.data = {}
    self.goodNodeList = {}

end


---@param data table rewards
---@param canGet boolean 可领取特效
---@param isGet boolean 已领取蒙版
---@param isShowNum boolean 显示奖励数量，不传默认显示
---@param isCheckNum boolean 是否检查道具数量
---@param isShowGoodsNumTips boolean 是否显示道具提示中的拥有数量
function CommonGoodsListLight:FreshBaseUI(data, canGet, isGet, isShowNum, isCheckNum, isShowGoodsTips, isShowGoodsNumTips, isShowSuperScript)
    if isNull(data) then
        return
    end
    if isNull(isShowNum) then--不传默认显示
        isShowNum = true
    end
    if isNull(isShowSuperScript) then
        isShowSuperScript = true
    end
    self.data = data

    --复用时隐藏多出来的
    local goCount = self.controller.transform.childCount
    if goCount > #data then
        for i = #data + 1, goCount do 
            CfUtils.SetActive(self.goodNodeList[i], false)
        end
    end

    -- local itemDefines = self.controller.
    for i = 1, #data do
        local go
        go = self.goodNodeList[i]
        if not go then
            -- go = CfUtils.InstantiateGo(self.GoodNode, self.controller.gameObject)
            go = self.poolBehaviour:GetPoolObject("GoodNode", self.controller.gameObject)
            go.name = "GoodNode"..i
            self.goodNodeList[i] = go.gameObject
        end
        self:RefreshGoodNode(go, data[i], isShowGoodsTips, isShowGoodsNumTips, isShowNum, isCheckNum, canGet, isGet, isShowSuperScript)
    end
end

function CommonGoodsListLight:RefreshGoodNode(go, goodData, isShowGoodsTips, isShowGoodsNumTips, isShowNum, isCheckNum, canGet, isGet, isShowSuperScript)
    ---@type GoodNodeMB
    local goEnv = CfUtils.GetLuaScr(go, "Game.Behaviours.GoodNodeMB")
    local goodsId = goodData.goodsId or goodData.id
    local num = goodData.goodsNum or goodData.num
    --@region 底部title 需要额外添加才会显示
    if not isNull(goodData.bottomTitle) then
        local txtBottom = go.transform:Find("TxtBottom")
        if txtBottom then
            CfUtils.FillText(txtBottom, goodData.bottomTitle)
        end
    end
    --@endregion
    goEnv:SetClickButtonAction(function()
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        if isTable(vo) then
            if not canGet then
                if isShowGoodsTips then
                    GameUtils.ShowCommonGoodsTipsBoard(go, goodsId, true)
                else
                    GameUtils.ShowCommonTipsBoard(go, vo.name, vo.desc, vo.quality, vo.id, isShowGoodsNumTips)
                end
            end
        end
    end)
    KTool.SetActive(go, true)
    goEnv:Reload(
            {
                goodsId = goodsId,
                isShowNo = isShowNum,
                text = self:GetText(isShowNum, num, goodsId, isCheckNum),
            }
    )

    if checkBool(isShowSuperScript)
    and not isNull(goodData.type) then
        goEnv:FillSuperScript(goodData.type)
    end

    if not isNull(canGet) then
        goEnv:SetCanGetEffectShow(canGet)
    end
    if not isNull(isGet) then
        goEnv:SetSanXingGainShow(isGet)
    end

    if isSet(goodData,"isSpecialReward") then
        goEnv:SetCanGetEffectShow(goodData.isSpecialReward)
    end
end

function CommonGoodsListLight:GetText(isShowNum, num, goodsId, isCheckNum)
    if not isShowNum then
        return nil
    end
    if isCheckNum then
        return GoodsUtils.GetGoodsText(goodsId, num, 1) --- GoodsUtils.GetConsumeGoodsText(goodsId, num)
    end
    if GameUtils.isZmFunction() then
        return 'x ' .. FormatCurrencyNum(num)
    else
        return 'x' .. FormatCurrencyNum(num)
    end
end

---可领取特效的显示与否
function CommonGoodsListLight:SetCanGetEffectShow(canGet)
    for i = 1, #self.data do
        local go
        go = self.goodNodeList[i]
        if go then
            local goEnv = CfUtils.GetLuaScr(go, "Game.Behaviours.GoodNodeMB")
            if goEnv then
                goEnv:SetCanGetEffectShow(canGet)
            end
        end
    end
end


---已领取蒙版的显示与否
function CommonGoodsListLight:SetIsGetMaskShow(isGet)
    for i = 1, #self.data do
        local go
        go = self.goodNodeList[i]
        if go then
            local goEnv = CfUtils.GetLuaScr(go, "Game.Behaviours.GoodNodeMB")
            if goEnv then
                goEnv:SetSanXingGainShow(isGet)
            end
        end
    end
end

---已领取蒙版的显示与否
function CommonGoodsListLight:SetIsGetMaskShowByData(isGet)
    for i = 1, #self.data do
        local go
        go = self.goodNodeList[i]
        if go then
            local goEnv = CfUtils.GetLuaScr(go, "Game.Behaviours.GoodNodeMB")
            if goEnv then
                local isGet = isGet
                if isSet(self.data[i],"isGet") then
                    isGet = self.data[i].isGet
                end
                goEnv:SetSanXingGainShow(isGet)
            end
        end
    end
end

function CommonGoodsListLight:SetBonusText()

end

function CommonGoodsListLight:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return CommonGoodsListLight